import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

/** Cache hints cannot turn query-local values or externally resolved services into shared result values. */
class RdfParserCacheVolatilityTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();

	@TempDir
	Path directory;

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void runtimeServiceEndpointsRetainFreshParserBlankNodes(boolean storedEndpoint) {
		String provider = storedEndpoint ? "<urn:endpoint> <urn:url> ?endpoint ."
				: "VALUES ?endpoint { <urn:rdf4j:parse> }";
		String query = "PREFIX parse: <http://rdf4j.org/function/parse#> SELECT ?s WHERE { " + provider
				+ " SERVICE ?endpoint { [] parse:content ?doc; parse:format \"text/turtle\" . ?s ?p ?o } }";
		assertFresh(query);
	}

	@ParameterizedTest
	@ValueSource(strings = { "BNODE()", "UUID()" })
	void nonRepeatableFunctionsRetainTheirFreshnessGuarantee(String function) {
		assertFresh("SELECT (" + function + " AS ?s) WHERE {} ");
	}

	private void assertFresh(String query) {
		LmdbStore store = new LmdbStore(directory.toFile());
		store.init();
		try (var connection = store.getConnection()) {
			connection.begin();
			connection.addStatement(VF.createIRI("urn:endpoint"), VF.createIRI("urn:url"),
					VF.createIRI("urn:rdf4j:parse"));
			connection.commit();
			TupleExpr expression = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
			MapBindingSet bindings = new MapBindingSet();
			bindings.addBinding("doc", VF.createLiteral("_:b <urn:p> <urn:o> ."));
			List<Value> subjects = new ArrayList<>();
			for (int evaluation = 0; evaluation < 2; evaluation++) {
				var previous = SlowQueryContextHolder.set(query, Query.QueryType.TUPLE, null, true);
				try (var rows = connection.evaluate(expression, null, bindings, false)) {
					assertTrue(rows.hasNext(), query);
					subjects.add(rows.next().getValue("s"));
					assertFalse(rows.hasNext(), query);
				} finally {
					SlowQueryContextHolder.restore(previous);
				}
			}
			assertNotEquals(subjects.get(0), subjects.get(1), query);
		} finally {
			store.shutDown();
		}
	}
}
